<script lang="ts">
 import {onMount} from 'svelte';
 import {PUBLIC_CONVEX_URL} from '$env/static/public';
 import {ConvexClient} from 'convex/browser';
 import {makeFunctionReference} from 'convex/server';
 import {authenticatedClient,sessionRequest} from '$lib/admin';
 import {beeCatalog} from '$lib/hive';
 let configured=$state(false), signedIn=$state(false), loading=$state(false), message=$state(''), snapshot:any=$state(null), name=$state('Drift'), symbol=$state('BTC-USDT'), candidateName=$state(''), artifactHash=$state(''), datasetHash=$state('');
 let client:ConvexClient|undefined;let unsubscribe:(()=>void)|undefined;
 let runtime:any=$state(null), modeBusy=$state(false);
 const ref=(name:string)=>makeFunctionReference<any>(name);
 async function run(name:string,args:Record<string,unknown>={}){if(!client)return;loading=true;message='';try{await client.mutation(ref(name),args);message='Cloud workspace updated.';}catch(e){message=e instanceof Error?e.message:String(e);}finally{loading=false;}}
 async function changeMode(mode:string){modeBusy=true;try{const result=await sessionRequest('/api/runtime/mode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode})});runtime={...runtime,...result};message='Execution mode confirmed by server.';}catch(e){message=e instanceof Error?e.message:String(e);}finally{modeBusy=false;}}
 onMount(()=>{
  configured=!!PUBLIC_CONVEX_URL;if(!configured)return;let disposed=false;
  (async()=>{try{const session=await sessionRequest('/api/auth/session');if(disposed)return;signedIn=!!session.user;if(!signedIn)return;const connected=authenticatedClient(PUBLIC_CONVEX_URL!);client=connected;unsubscribe=connected.onUpdate(ref('hive:dashboard'),{},data=>snapshot=data,(e:Error)=>message=e.message);try{runtime=await sessionRequest('/api/runtime/status');}catch{/* Runtime unavailable remains explicitly unverified. */}}catch(e){message=e instanceof Error?e.message:String(e);}})();
  return()=>{disposed=true;unsubscribe?.();void client?.close();};
 }); function strategy(n:string){return n==='Drift'?'trend':n==='Rebound'?'reversion':n==='Breaker'?'breakout':'research';}
</script>
<div class="cloud-hive">
 <div class="cloud-heading"><div><span class="eyebrow">PERSISTENT RESEARCH</span><h3>Keep your hive working.</h3><p>Your persistent hive, verified execution controls and model evidence.</p></div><span class="tiny-badge">{configured?'Cloud configured':'Setup required'}</span></div>
 {#if !configured}<div class="cloud-empty"><strong>Your local workspace is ready.</strong><p>The cloud service requires an enabled Convex deployment and sign-in provider. Browser-local paper accounts stay separate from cloud portfolios. No background execution is claimed until connected.</p></div>
 {:else if !signedIn}<a class="outline-button" href="/login">Sign in to your cloud hive →</a>
 {:else}<div class="cloud-actions"><a class="outline-button" href="/admin">Operations console</a>{#if !snapshot?.portfolio}<button class="outline-button" disabled={loading} onclick={()=>run('hive:initialize')}>Initialize $10,000 paper portfolio</button>{:else}<strong>${snapshot.portfolio.cash.toLocaleString('en-US',{maximumFractionDigits:2})} paper cash</strong><button class="outline-button" disabled={loading} onclick={()=>run('hive:killSwitch',{killed:!snapshot.portfolio.killed})}>{snapshot.portfolio.killed?'Reset kill switch':'Pause all Bees'}</button>{/if}</div>
 <div class="cloud-empty"><strong>Execution: {runtime?.config?.mode??runtime?.mode??'unverified'}</strong><div class="cloud-actions"><button class="outline-button" disabled={modeBusy||!runtime} onclick={()=>changeMode('paper')}>Paper trading</button><button class="outline-button" disabled={modeBusy||!runtime?.liveReady} onclick={()=>changeMode('live')}>Live trading {runtime?.liveReady?'':'· locked'}</button></div><p>{runtime?.liveLockReason??'Live execution requires verified venue credentials, limits and explicit server authorization.'}</p><p>Daily retraining · 04:00 Africa/Lagos · {runtime?.training?.activation??'deployment not verified'}. Last run: {runtime?.training?.lastRun??'no verified run'}. Existing model stays active unless a candidate passes chronological improvement checks.</p></div>{#if snapshot?.portfolio}<form class="cloud-form" onsubmit={(e)=>{e.preventDefault();run('hive:createBee',{name,symbol,strategy:strategy(name)});}}><label>Bee<select bind:value={name}>{#each beeCatalog as bee}<option>{bee.name}</option>{/each}</select></label><label>Market<select bind:value={symbol}><option>BTC-USDT</option><option>ETH-USDT</option><option>SOL-USDT</option></select></label><button class="outline-button" disabled={loading}>Register Bee</button></form>
 <p class="cloud-note">Pausing stops automated decisions and leaves holdings open; close them explicitly. Drift, Rebound and Breaker use deterministic research baselines. Other Bees register in research mode and abstain. No trained weights are installed.</p>
 <div class="cloud-rows">{#each snapshot.bees as bee}<div><strong>{bee.name}</strong><span>{bee.symbol} · {bee.strategy}</span><span>{bee.lastDecision??'Waiting for 30 contiguous minute observations'}</span><button class="outline-button" disabled={loading||bee.strategy==='research'} onclick={()=>run('hive:setBeeActive',{beeId:bee._id,active:!bee.active})}>{bee.active?'Pause':'Activate paper'}</button>{#if bee.quantity>0}<button class="outline-button" disabled={loading} onclick={()=>run('hive:closeBeePosition',{beeId:bee._id})}>Close paper holding</button>{/if}</div>{:else}<p>Register your first Bee to begin.</p>{/each}</div>
 <details><summary>Register a model candidate</summary><p>Manifest registration records provenance. It does not train or activate a model.</p><form class="cloud-form candidate" onsubmit={(e)=>{e.preventDefault();run('hive:registerCandidate',{name:candidateName,artifactHash,datasetHash});}}><label>Name<input bind:value={candidateName} maxlength="100" required/></label><label>Artifact SHA-256<input bind:value={artifactHash} pattern="[a-f0-9]{64}" required/></label><label>Dataset SHA-256<input bind:value={datasetHash} pattern="[a-f0-9]{64}" required/></label><button class="outline-button" disabled={loading}>Register candidate</button></form>{#each snapshot.candidates as candidate}<p>{candidate.name} · {candidate.state}</p>{/each}</details>
 <div class="cloud-rows"><h4>Cloud paper ledger</h4>{#each snapshot.fills.slice(0,20) as fill}<div><span>{new Date(fill.at).toLocaleString()}</span><strong>{fill.side.toUpperCase()}</strong><span>{fill.quantity.toFixed(6)} @ ${fill.price.toFixed(2)}</span><span>Fee ${fill.fee.toFixed(4)}</span></div>{:else}<p>No simulated fills. Active baselines wait for sufficient fresh observations.</p>{/each}</div>{/if}{/if}
 {#if message}<p role="status">{message}</p>{/if}
</div>
<style>
 .cloud-hive{padding:24px}.cloud-heading{display:flex;justify-content:space-between;gap:20px}.cloud-heading h3{font-size:22px;margin:8px 0}.cloud-hive p{color:#8c96aa;font-size:12px;line-height:1.8}.cloud-empty{padding:24px;background:#111720;border:1px solid #252d3a;border-radius:10px;margin-top:16px}.cloud-actions,.cloud-form{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin:20px 0}.cloud-form label{display:grid;gap:7px;color:#9aa4b5;font-size:12px}.cloud-form input,.cloud-form select{background:#0b1018;color:#e1e7f0;border:1px solid #2c3545;border-radius:7px;padding:10px}.cloud-rows>div{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:15px 0;border-bottom:1px solid #242b37;font-size:12px}.cloud-rows span{color:#8d97a8}.cloud-hive details{margin:22px 0}.cloud-hive summary{cursor:pointer;color:#e2ba59}.candidate input{max-width:240px}
</style>
